count = 0
for k in fixes:
    if k in data["cache"]:
        data["cache"][k] = fixes[k]
        count += 1
    else:
        print(f"Key not found: {k}")

with open("hiragana_data.json", "w", encoding="utf-8") as f:
    json.dump(data, f, ensure_ascii=False, indent=4)
print(f"Fixed {count} entries directly.")
